class Solution:
    def minimumTime(self, s):
        n = len(s)
        P = [0] * (n + 1)
        for i, ch in enumerate(s):
            P[i + 1] = P[i] + (ch == '1')
        best = n
        run = 0
        for j in range(n):
            run = min(run, j - 2 * P[j])
            best = min(best, (n - 1 - j) + 2 * P[j + 1] + run)
        return best

