class Solution {
public:
    int minimumTime(string s) {
        int n = s.size();
        vector<int> P(n + 1, 0);
        for (int i = 0; i < n; i++) P[i + 1] = P[i] + (s[i] == '1');
        int best = n, run = 0;
        for (int j = 0; j < n; j++) {
            run = min(run, j - 2 * P[j]);
            best = min(best, (n - 1 - j) + 2 * P[j + 1] + run);
        }
        return best;
    }
};

