class Solution {
    public int minimumTime(String s) {
        int n = s.length();
        int[] P = new int[n + 1];
        for (int i = 0; i < n; i++) P[i + 1] = P[i] + (s.charAt(i) == '1' ? 1 : 0);
        int best = n, run = 0;
        for (int j = 0; j < n; j++) {
            run = Math.min(run, j - 2 * P[j]);
            best = Math.min(best, (n - 1 - j) + 2 * P[j + 1] + run);
        }
        return best;
    }
}

