var minimumTime = function(s) {
    const n = s.length, P = new Array(n + 1).fill(0);
    for (let i = 0; i < n; i++) P[i + 1] = P[i] + (s[i] === '1' ? 1 : 0);
    let best = n, run = 0;
    for (let j = 0; j < n; j++) {
        run = Math.min(run, j - 2 * P[j]);
        best = Math.min(best, (n - 1 - j) + 2 * P[j + 1] + run);
    }
    return best;
};
